import {
  parseSearchResults,
  parseTranscript,
  findMatchWithContext,
} from "./filmot-parse";

// Faithful-but-small fixture mirroring the real filmot search/sidebyside markup:
// two result cards (one auto-generated, one manual) and a #subtitlesIn transcript
// where the phrase "vara åtgång" is split across s202 (…vara) and s203 (åtgång…).
const HTML = `
<div id="results" class="col-xl-2">
  <div id="vcard_NxAaT1Yj9OE" class="vcard0 border list-group-item bg-light text-dark">
    <a rel="nofollow" id="vlink0" class="vlink0" href="https://filmot.com/search/%22%C3%A5tg%C3%A5ng%22/NxAaT1Yj9OE/1?lang=sv">
      <img id="thumb0" class="rounded" src="0.jpg"> <br> GTA 5 LASERVAPEN!!! </a>
    <span class="badge"><i class="fa fa-eye"></i>606K</span>
    <span class="badge"><i class="fa fa-thumbs-up"></i>8.7K</span>
    <span class="badge">10 Jan 2019</span>
    <a rel="nofollow" href="https://filmot.com/sidebyside/NxAaT1Yj9OE/auto.sv/auto.sv/Swedish+%28auto-generated%29/Swedish+%28auto-generated%29/GTA">flag</a>
  </div>
  <div id="vcard_Manual123XY" class="vcard1 border list-group-item bg-light text-dark">
    <a rel="nofollow" id="vlink1" class="vlink1" href="https://filmot.com/search/%22%C3%A5tg%C3%A5ng%22/Manual123XY/1?lang=sv">
      <img id="thumb1" class="rounded" src="1.jpg"> <br> Riktig Titel </a>
    <span class="badge"><i class="fa fa-eye"></i>12K</span>
    <span class="badge"><i class="fa fa-thumbs-up"></i>340</span>
    <span class="badge">05 Mar 2021</span>
    <a rel="nofollow" href="https://filmot.com/sidebyside/Manual123XY/sv/sv/Swedish/Swedish/Riktig">flag</a>
  </div>
</div>
<div id="subtitlesIn" class="scroll-subtitles">
  <div class="" id="s201"><a href="javascript:jtt(201,668.1);">▶&nbsp;</a>något helt annat innan</div>
  <div class="" id="s202"><a href="javascript:jtt(202,671.639);">▶&nbsp;</a>här nere i alla fall Det brukar ju vara</div>
  <div class="" id="s203"><a href="javascript:jtt(203,672.959);">▶&nbsp;</a>åtgång på dem ska vi se vart du är</div>
  <div class="" id="s204"><a href="javascript:jtt(204,675.0);">▶&nbsp;</a>på väg någonstans</div>
</div>`;

describe("parseSearchResults", () => {
  test("extracts one card per vcard with id, title, transcript url", () => {
    const cards = parseSearchResults(HTML);
    expect(cards.map((c) => c.videoId)).toEqual(["NxAaT1Yj9OE", "Manual123XY"]);
    expect(cards[0].title).toBe("GTA 5 LASERVAPEN!!!");
    expect(cards[1].title).toBe("Riktig Titel");
    expect(cards[0].transcriptUrl).toContain("/NxAaT1Yj9OE/1?lang=sv");
  });

  test("returns an absolute transcript URL even when the live page uses a relative href", () => {
    const html = `<div id="vcard_HUN9RBy05WY" class="vcard0">
      <a id="vlink0" href="/search/%22bita%22/HUN9RBy05WY/1?lang=sv"><img src="x.jpg"><br>Titel</a>
      <a href="/sidebyside/HUN9RBy05WY/sv/sv/Swedish/Swedish/Titel">f</a></div>`;
    const [c] = parseSearchResults(html);
    expect(c.transcriptUrl).toBe("https://filmot.com/search/%22bita%22/HUN9RBy05WY/1?lang=sv");
  });

  test("flags auto-generated vs manual captions from the sidebyside link", () => {
    const cards = parseSearchResults(HTML);
    expect(cards[0].isAutoGenerated).toBe(true);
    expect(cards[1].isAutoGenerated).toBe(false);
  });

  test("captures view/like/date badges", () => {
    const [c0] = parseSearchResults(HTML);
    expect(c0.views).toBe("606K");
    expect(c0.likes).toBe("8.7K");
    expect(c0.date).toBe("10 Jan 2019");
  });
});

describe("parseTranscript", () => {
  test("parses subtitle lines with index, timestamp and cleaned text", () => {
    const { lines } = parseTranscript(HTML);
    expect(lines).toHaveLength(4);
    expect(lines[1]).toEqual({
      idx: 202,
      ts: 671.639,
      text: "här nere i alla fall Det brukar ju vara",
    });
    expect(lines[2].text).toBe("åtgång på dem ska vi se vart du är"); // ▶ and &nbsp; stripped
  });

  test("strips the ▶ marker whether it is the literal char OR the numeric entity &#9654;", () => {
    // Live filmot encodes the play glyph as &#9654; (not the literal ▶ the sample
    // used); if it isn't decoded it leaks to the START of every line and breaks a
    // phrase that spans a line boundary once the lines are joined.
    const html = `<div id="subtitlesIn">
      <div id="s1"><a href="javascript:jtt(1,10.0);">&#9654;&nbsp;</a>att sopa rent</div>
      <div id="s2"><a href="javascript:jtt(2,12.0);">&#9654;&nbsp;</a>framför sin egen dörr</div>
    </div>`;
    const { lines } = parseTranscript(html);
    expect(lines.map((l) => l.text)).toEqual(["att sopa rent", "framför sin egen dörr"]);
    // joined (single-space) must contain the contiguous phrase
    expect(lines.map((l) => l.text).join(" ")).toContain("sopa rent framför sin egen dörr");
  });
});

describe("findMatchWithContext", () => {
  const linesOf = () => parseTranscript(HTML).lines;

  test("finds a single word and returns N lines before / after", () => {
    const re = /(?<![\p{L}\p{N}])(?:åtgång)(?![\p{L}\p{N}])/iu;
    const m = findMatchWithContext(linesOf(), re, 1, 1);
    expect(m.idx).toBe(203);
    expect(m.tsStart).toBe(672.959);
    expect(m.contextLines.map((l) => l.idx)).toEqual([202, 203, 204]);
  });

  test("matches a phrase split across adjacent lines and spans both", () => {
    const re = /vara\s+åtgång/iu; // "vara" ends s202, "åtgång" starts s203
    const m = findMatchWithContext(linesOf(), re, 0, 0);
    // context with 0/0 should still include both touched lines
    expect(m.contextLines.map((l) => l.idx)).toEqual([202, 203]);
  });

  test("returns null when the pattern is absent", () => {
    expect(findMatchWithContext(linesOf(), /nonexistentword/iu, 2, 2)).toBeNull();
  });
});
